    function __ESBMC_assume(bool) internal pure {}

    function run(uint valueSent) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (valueSent)); require(valueSent <= 1000000000000000000000000000000);
        require(address(this).balance >= valueSent);

        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;

        c.play{value: valueSent}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {} else {}

        assert(c.bank() == bankBefore);
